from pages import *
from fig import *
i=14
def scooter(): return '<circle cx="-24" cy="0" r="10" fill="#333"/><circle cx="24" cy="0" r="10" fill="#333"/><path d="M-30 -10 h40 l10 -24 h8 M-10 -10 q0 -14 20 -14" fill="#1d6fb8" stroke-width="2.5"/>'
COV=covart('A śamī tree with a bow and quiver hidden in its branches, tools and a scooter decorated with flowers and kuṅkuma for Āyudha Pūjā, and a saffron victory flag',
 ground(440,220,196)+g(110,196,1.5,shami())+g(110,120,.7,bow())+g(250,190,1.1,scooter())+g(250,150,.5,'<circle r="10" fill="#ff8c1a"/>')+g(330,190,.9,tools())+g(400,196,1.1,flag()))
pages=[foreword(i,['The nine nights end and the festival turns outward. The ninth day, <b>Mahānavamī</b>, is the day of <b>Āyudha Pūjā</b>, when tools, weapons, vehicles and instruments are worshipped. The tenth day, <b>Vijayadaśamī</b>, is the day of victory.','On these two days the stories of the season come together: the Devī’s victory over Mahiṣa, the Pāṇḍavas taking back their weapons from the śamī tree, and Rāma’s victory over Rāvaṇa. This part tells each, and explains the customs that grew from them.'],
 [('z','Why worship a scooter?'),('b','Because it carries you to work. Āyudha Pūjā thanks every tool that keeps the household going.')]),
 glance([('Mahānavamī','Ninth day of the bright half of Āśvina; last of the nine nights'),('Āyudha Pūjā','Worship of tools, weapons, vehicles, machines and instruments (Karnataka, Tamil Nadu, Kerala and beyond)'),('Vijayadaśamī','Tenth day: “the victorious tenth”, Dasarā'),('Śamī Pūjā','Worship of the śamī (banni) tree, remembering the Pāṇḍavas’ hidden weapons'),('Other rites','Aparājitā Pūjā; sīmollaṅghana (crossing the boundary); Rāvaṇa dahana in the north'),('New beginnings','Vidyārambha (first letters), new ventures, journeys')],svg(560,160,'Tools decorated with flowers on the left, and a śamī tree with a victory flag on the right',ground(560,160,140)+g(120,135,1,tools())+g(230,140,1,scooter())+g(380,140,1,shami())+g(480,140,1,flag()))),
 reading('navami','MAHĀNAVAMĪ','The great ninth day',svg(560,170,'A fire offering (homa) with flames in a square pit, a priest pouring ghee, and the Devī’s image behind',g(280,150,1,'<rect x="-40" y="-10" width="80" height="20" fill="#a8553a" stroke="#111" stroke-width="2"/>')+g(280,140,1.2,flames())+g(170,155,.9,sage())+g(400,150,.9,devi(items=('trident','sword','lotus','abhaya')))),[
  '<b>The last night.</b> <b>Mahānavamī</b> is the ninth day, belonging in the nine-Durgā order to '+link(11,'Siddhidātrī')+'. Those who have read the Devī Māhātmya through the nights finish it today.','<b>Homa.</b> Many homes and temples close the reading with a <b>homa</b>, a fire offering, with verses of the Devī Māhātmya offered into the fire.','<b>In Bengal.</b> Mahānavamī is the last full day of Durgā Pūjā, with its own great worship and feasting before the farewell.','<b>In the old kingdoms.</b> Vijayanagara called the whole festival the <b>Mahānavamī</b>, and its kings held their grandest court on these days; the Mysuru Dasarā inherited that tradition ('+link(15,'Part 16')+').'],
  [('z','So the ninth day is a finishing line?'),('b','For the reading and the vow, yes. Then you rest, and the tenth day starts something new.')],'Mahānavamī: <b>the reading finished, the fire offering made</b>.'),
 cards('ayudha','ĀYUDHA PŪJĀ','Thanking the tools of life',svg(560,190,'A row of objects marked with turmeric and kuṅkuma and garlanded: a plough, a sewing machine, a computer, a car, a veena and a sword',ground(560,190,170,'#e9d6c0')+g(70,170,.9,'<path d="M-30 0 l40 -40 l10 6 l-30 40z" fill="#8a5a2a"/>')+g(160,170,1,'<rect x="-30" y="-30" width="60" height="30" fill="#3a3a40"/><path d="M-20 -30 v-14 h30 v14" fill="none" stroke-width="3"/>')+g(250,170,1,'<rect x="-28" y="-40" width="56" height="34" fill="#1d6fb8"/><rect x="-34" y="-6" width="68" height="6" fill="#999"/>')+g(350,170,1.1,scooter())+g(440,150,.6,vina())+g(510,170,1,sword())+''.join(f'<circle cx="{x}" cy="120" r="5" fill="#ff8c1a" stroke="#111"/>' for x in (70,160,250,350,440,510))),[
  ('🔧','What is worshipped','Tools, weapons, vehicles, machines, computers, instruments, books: anything a household or trade works with. They are cleaned, marked with turmeric and kuṅkuma, and garlanded.'),
  ('🗡️','Why “āyudha”','<i>Āyudha</i> means weapon. Kings worshipped their weapons and horses on this day; farmers their ploughs; craftsmen their tools; today drivers their cars.'),
  ('📜','The story','Two stories are told: the Devī’s weapons were worshipped after her victory; and the Pāṇḍavas took back their weapons from the śamī tree on this day.'),
  ('🙏','Rest for the tools','On the day of worship the tools are not used. In Karnataka Āyudha Pūjā is usually on Mahānavamī; the tools return to work on Vijayadaśamī.')],
  [('z','So my laptop gets the day off?'),('b','It gets thanked and rests. Tomorrow it works again, blessed.')],'Every tool that feeds the family is <b>thanked and given a day of rest</b>.'),
 story('shami','THE PĀṆḌAVAS AND THE ŚAMĪ TREE','Mahābhārata, Virāṭa Parva',strip('Three panels: the five Pāṇḍavas hiding weapons in a śamī tree; Arjuna, disguised, driving prince Uttara’s chariot; Arjuna taking back his bow Gāṇḍīva from the tree',[(g(72,160,1,shami())+g(72,90,.5,bow()),'#cfe0b8'),(g(72,150,.7,person('#7a3fa0'))+g(72,160,.6,'<circle cx="-20" r="10" fill="#8a5a2a"/><circle cx="20" r="10" fill="#8a5a2a"/><rect x="-30" y="-20" width="60" height="16" fill="#e0a800"/>'),'#fff3cf'),(g(72,160,1,shami())+g(40,150,.7,person('#1d6fb8'))+g(58,110,.5,bow()),'#cfe0b8')],['weapons hidden in the śamī','Arjuna in disguise','Gāṇḍīva taken back']),
  'The Mahābhārata gives the oldest story behind śamī worship.',[
  'After losing at dice, the five <b>Pāṇḍavas</b> spent twelve years in the forest and had to live a thirteenth year in disguise. If found, they would have to begin the exile again.','Before entering King Virāṭa’s city in disguise, they wrapped their weapons, including Arjuna’s great bow <b>Gāṇḍīva</b>, and hid them in a <b>śamī</b> tree near a cremation ground, where no one would look.','At the end of the year the Kauravas raided Virāṭa’s cattle. Arjuna, disguised as a dance teacher, drove the young prince Uttara’s chariot to meet them.','He went to the śamī tree, took down Gāṇḍīva, revealed who he was and drove back the whole Kaurava army.','Tradition says the Pāṇḍavas worshipped the tree for keeping their weapons safe; so the śamī is worshipped on Vijayadaśamī and tools on Āyudha Pūjā.'],
  [('z','So the tree was a weapons locker?'),('b','A trusted guardian. The lesson people draw: protect what is precious, and thank whoever kept it safe.')],'The śamī kept the Pāṇḍavas’ weapons; <b>on Vijayadaśamī we thank it</b>.'),
 story('rama','RĀMA’S VICTORY','Why the north burns Rāvaṇa on the tenth day',strip('Three panels: Rāma with his bow; the ten-headed Rāvaṇa; a giant Rāvaṇa effigy burning',[(g(72,150,.8,person('#1d6fb8'))+g(100,110,.7,bow()),'#dfe9f6'),(g(72,165,.8,effigy()),'#fde4e4'),(g(72,165,.75,effigy())+g(72,170,.8,flames()),'#1f1a2e')],['Rāma','Rāvaṇa','the effigy burns']),
  'Across much of India Vijayadaśamī is above all the day of Rāma’s victory.',[
  'Rāvaṇa, the ten-headed king of Laṅkā, carried off Sītā, and Rāma and Lakṣmaṇa, with Hanumān and the vānara army, went to war to bring her back.','After a long battle, Rāma killed Rāvaṇa. Popular tradition places this victory on the tenth day of Āśvina, though the Vālmīki Rāmāyaṇa does not fix the date this way.','A Bengali and wider tradition adds that Rāma first worshipped Durgā, out of season, to win: the <i>akāla bodhana</i>.','In the north, <b>Rāmlīlā</b>, the staged Rāmāyaṇa, plays through the nine nights, and on the tenth huge effigies of Rāvaṇa, Kumbhakarṇa and Meghanāda are burnt with fireworks.','The burning stands for the end of arrogance and wrong: the ten heads are often read as ten vices.'],
  [('z','Do we burn Rāvaṇa in Mysuru?'),('b','Not traditionally. Mysuru’s tenth day belongs to Cāmuṇḍī and the banni tree. But the Rāma story is told here too.')],'Rāma’s victory and Rāvaṇa’s burning: <b>the north’s Vijayadaśamī</b>.'),
 reading('aparajita','APARĀJITĀ AND CROSSING THE BOUNDARY','The old rites of the tenth day',svg(560,180,'A king on horseback with a sword crossing a village boundary stone, a small goddess shrine of Aparājitā beside the road',ground(560,180,150,'#e9d6c0')+'<rect x="270" y="110" width="16" height="40" fill="#999" stroke="#111" stroke-width="2"/>'+g(170,150,1,'<path d="M-40 0 v-20 q0 -20 30 -22 h40 q20 0 24 -20 l10 4 l-4 30 h-10 v28 h-10 v-20 h-50 v20z" fill="#a8553a"/>')+g(170,90,.8,person('#c0392b'))+g(200,70,.5,sword())+g(420,150,.9,devi(items=('lotus','abhaya')))+lab(278,170,'the boundary')+lab(420,170,'Aparājitā')),[
  '<b>Aparājitā.</b> Medieval ritual digests prescribe the worship of <b>Aparājitā</b>, “the unconquered”, a form of the Devī, on the afternoon of Vijayadaśamī, ideally near a śamī tree. Kings did it before setting out on campaign.','<b>Sīmollaṅghana.</b> After that worship, the king (and later the townspeople) crossed the boundary (<i>sīmā</i>) of the town: the season of rains was over, and armies and traders could travel again.','<b>The tenth day’s procession.</b> That royal journey to the śamī tree beyond the town is the root of Mysuru’s procession to the Banni Maṇṭapa ('+link(15,'Part 16')+').','<b>For us.</b> Crossing a boundary is read as beginning boldly: the tenth day is the day to step beyond old limits.'],
  [('z','Kings went to war on Vijayadaśamī?'),('b','In the old calendar, campaigns began after the monsoon, and this was the auspicious day to set out.')],'Aparājitā, the unconquered; <b>the boundary crossed</b>.'),
 reading('banni','BANNI: LEAVES LIKE GOLD','Karnataka’s Vijayadaśamī custom',svg(560,180,'People exchanging small śamī leaves in their palms, with a śamī tree behind',ground(560,180,160)+g(110,160,1.2,shami())+g(300,160,1,person('#c0392b'))+g(380,160,1,person('#2a9d6f'))+g(340,110,.6,'<ellipse rx="14" ry="6" fill="#5a8a3a"/>')+g(470,160,.9,child())),[
  '<b>Banni Pūjā.</b> In Karnataka the śamī is <b>banni</b>, in Telugu <b>jammi</b>. On Vijayadaśamī families visit a banni tree, walk around it, worship it and pluck a few leaves.','<b>Leaves as gold.</b> The leaves are exchanged with family and friends, and touched to the feet of elders in respect. A popular Kannada saying, spoken as the leaves are given, wishes that the receiver may “take banni and live like gold”.','<b>Maharashtra’s gold.</b> In Maharashtra the leaves of the <b>āpṭā</b> tree are given as “gold” (<i>sonā</i>), with a story: the young Kautsa needed gold to pay his teacher; King Raghu, out of wealth, prayed, and gold rained on a śamī (or āpṭā) tree.','<b>A prayer.</b> A short verse is often recited to the śamī, praising it as the tree that destroys sin, carried Arjuna’s bow and was dear to Rāma.'],
  [('z','So leaves are money on that day?'),('b','Better than money: blessings. The gold is in the giving.')],'Banni leaves exchanged: <b>wishes of gold</b>.'),
 reading('vidyarambha','NEW BEGINNINGS','Vidyārambha and the first letters',svg(560,180,'A small child on a parent’s lap writing letters with a finger in a plate of rice, guided by an elder',g(240,160,1.1,person('#c0392b',seat=True))+g(250,120,.8,child())+g(330,150,1.2,'<ellipse rx="40" ry="10" fill="#e0a800"/>'+''.join(f'<circle cx="{x}" cy="{y}" r="1.5" fill="#fff"/>' for x,y in [(-20,-2),(-8,2),(6,-3),(18,1),(28,-2)])+'<path d="M-14 -2 q6 -6 12 0 q6 6 12 0" fill="none" stroke="#c0392b" stroke-width="2"/>')+g(420,160,1,sage())),[
  '<b>Vidyārambha.</b> In Kerala and parts of Karnataka and Tamil Nadu, Vijayadaśamī is the day small children begin learning. In Kerala the rite is called <b>Vidyārambham</b> or <i>Ezhuthiniruthu</i>.','<b>How it is done.</b> The child sits on an elder’s or teacher’s lap and traces the first letters in a plate of rice with a finger, often beginning with a sacred phrase such as <i>hari śrī</i>; the elder may write it on the child’s tongue with gold.','<b>The books return.</b> In homes that kept Sarasvatī Pūjā ('+link(13,'Part 14')+'), the books and instruments are taken back with a prayer and used: a few lines read, a few notes played.','<b>Other beginnings.</b> Businesses open new accounts, people buy vehicles or begin journeys: all under the sign of victory.'],
  [('z','Why rice?'),('b','Rice is wealth and nourishment. The child’s first letters are written in plenty.')],'First letters in rice: <b>the day learning begins</b>.'),
 end(i,['<b>Mahānavamī.</b> The reading finished, the homa offered.','<b>Āyudha Pūjā.</b> Tools, vehicles and instruments thanked and rested.','<b>Śamī.</b> The Pāṇḍavas’ weapons kept safe in the tree; banni leaves exchanged as gold.','<b>Rāma.</b> His victory over Rāvaṇa; effigies burnt in the north.','<b>Beginnings.</b> Aparājitā, the boundary crossed, Vidyārambha.'],'Part 16 brings it all together in Mysuru: four centuries of the royal Dasarā, the golden howdah and the march to the banni tree.','Mahānavamī and Vijayadaśamī'),
 sources([('Mahābhārata:','Virāṭa Parva (weapons hidden in a śamī; Arjuna and Uttara), as summarised in Wikipedia, “Vijayadashami”.'),('Customs:','Wikipedia, “Ayudha Puja”, “Vijayadashami”, “Mysore Dasara” (Banni tree, Bannimantap). Outlook India, “Dussehra: Shami Puja” (Raghu and Kautsa; Aparājitā, sīmollaṅghana). Hindutone, Vijayadashami state-wise guide (Aparājitā in Hemādri and Nirṇaya Sindhu; Vidyārambha).')],'Rāma’s victory dated to Vijayadaśamī (popular, not in Vālmīki); the wording of the Kannada banni saying; whether Kautsa’s gold fell on śamī or āpṭā (tellings differ).','Customs in their common forms.')]
build(i,'PART 15 OF 16 · TOOLS · TREES · VICTORY',COV,'The śamī tree and the tools of life',
 'The ninth and tenth days: <b>Mahānavamī</b>, <b>Āyudha Pūjā</b>, the <b>Pāṇḍavas’ śamī tree</b>, <b>Rāma’s victory</b>, Aparājitā, the banni leaves and the first letters of <b>Vidyārambha</b>.',
 'Mahānavamī and Vijayadaśamī: Āyudha Pūjā, the Pāṇḍavas and the śamī tree, Rāma’s victory and Rāvaṇa dahana, Aparājitā and sīmollaṅghana, banni leaves exchanged as gold, and Vidyārambha. Part 15 of the illustrated Navarātri series.',pages)
